    'School Profile' => ['Profil Sekolah', '学校资料', 'பள்ளிச் சுயவிவரம்'],
    'State / District' => ['Negeri / Daerah', '州／县', 'மாநிலம் / மாவட்டம்'],
    'How It Works' => ['Cara Program Berfungsi', '参与方式', 'செயல்படும் முறை'],
    'Student participation journey' => ['Perjalanan penyertaan murid', '学生参与流程', 'மாணவர் பங்கேற்புப் பயணம்'],
    'School Registration' => ['Pendaftaran Sekolah', '学校注册', 'பள்ளிப் பதிவு'],
    'The school registers in the portal and appoints a school team teacher as the main coordinator.' => ['Sekolah mendaftar dalam portal dan melantik guru pasukan sekolah sebagai penyelaras utama.', '学校在门户注册，并委任学校团队教师担任主要协调员。', 'பள்ளி இணையதளத்தில் பதிவு செய்து பள்ளிக் குழு ஆசிரியரை முதன்மை ஒருங்கிணைப்பாளராக நியமிக்கிறது.'],
    'Student Membership' => ['Keahlian Murid', '学生会员资格', 'மாணவர் உறுப்பினர் நிலை'],
    'Students register under their school and pay a one-time RM100 participation fee.' => ['Murid mendaftar di bawah sekolah masing-masing dan membayar yuran penyertaan sekali sahaja sebanyak RM100.', '学生通过所属学校注册，并一次性支付 RM100 参与费。', 'மாணவர்கள் தங்கள் பள்ளியின் கீழ் பதிவு செய்து RM100 ஒருமுறை பங்கேற்புக் கட்டணத்தைச் செலுத்துகிறார்கள்.'],
    'Learning & Attendance' => ['Pembelajaran dan Kehadiran', '学习与出勤', 'கற்றலும் வருகையும்'],
    'Active students can participate in weekly learning modules, school activities and attendance-based programme sessions.' => ['Murid aktif boleh menyertai modul pembelajaran mingguan, aktiviti sekolah dan sesi program berdasarkan kehadiran.', '活跃学生可参加每周学习模块、学校活动及有出勤记录的计划课程。', 'செயலில் உள்ள மாணவர்கள் வாராந்திர கற்றல் தொகுதிகள், பள்ளிச் செயல்பாடுகள் மற்றும் வருகை அடிப்படையிலான திட்ட அமர்வுகளில் பங்கேற்கலாம்.'],
    'Students and schools can join eligible events, competitions and tournaments through the programme portal.' => ['Murid dan sekolah boleh menyertai acara, pertandingan dan kejohanan yang layak melalui portal program.', '学生与学校可通过计划门户参加符合资格的活动、比赛与锦标赛。', 'மாணவர்களும் பள்ளிகளும் திட்ட இணையதளம் மூலம் தகுதியான நிகழ்வுகள் மற்றும் போட்டிகளில் பங்கேற்கலாம்.'],
    'The student participation fee is RM100, payable one time only.' => ['Yuran penyertaan murid ialah RM100, dibayar sekali sahaja.', '学生参与费为 RM100，仅需支付一次。', 'மாணவர் பங்கேற்புக் கட்டணம் RM100; ஒருமுறை மட்டுமே செலுத்த வேண்டும்.'],
    'RM100 one-time participation fee' => ['Yuran penyertaan RM100 sekali sahaja', '一次性 RM100 参与费', 'RM100 ஒருமுறை பங்கேற்புக் கட்டணம்'],
    'Access to programme learning modules' => ['Akses kepada modul pembelajaran program', '使用计划学习模块', 'திட்டக் கற்றல் தொகுதிகளுக்கான அணுகல்'],
    'Attendance and participation tracking' => ['Rekod kehadiran dan penyertaan', '出勤与参与记录', 'வருகை மற்றும் பங்கேற்புப் பதிவு'],
    'Eligibility to join selected events and competitions' => ['Kelayakan menyertai acara dan pertandingan terpilih', '符合指定活动与比赛的参与资格', 'தேர்ந்தெடுக்கப்பட்ட நிகழ்வுகள் மற்றும் போட்டிகளில் பங்கேற்கத் தகுதி'],
    'Student STEM & Esports certificate access' => ['Akses sijil STEM dan E-Sukan murid', '获取学生 STEM 与电子竞技证书', 'மாணவர் STEM மற்றும் மின்னணு விளையாட்டுச் சான்றிதழுக்கான அணுகல்'],
    'Structured weekly digital learning' => ['Pembelajaran digital mingguan berstruktur', '系统化每周数字学习', 'முறையான வாராந்திர டிஜிட்டல் கற்றல்'],
    'Active students can follow structured learning modules that combine digital knowledge, practical activities, responsible technology use and competition-related skills.' => ['Murid aktif boleh mengikuti modul pembelajaran berstruktur yang menggabungkan pengetahuan digital, aktiviti amali, penggunaan teknologi secara bertanggungjawab dan kemahiran pertandingan.', '活跃学生可学习结合数字知识、实践活动、负责任的技术使用及竞赛技能的系统化模块。', 'செயலில் உள்ள மாணவர்கள் டிஜிட்டல் அறிவு, செய்முறை செயல்பாடுகள், பொறுப்பான தொழில்நுட்பப் பயன்பாடு மற்றும் போட்டித் திறன்களை இணைக்கும் முறையான கற்றல் தொகுதிகளைப் பின்பற்றலாம்.'],
    'Digital Literacy & Responsible Technology' => ['Literasi Digital dan Teknologi Bertanggungjawab', '数字素养与负责任的技术使用', 'டிஜிட்டல் எழுத்தறிவும் பொறுப்பான தொழில்நுட்பமும்'],
    'Digital citizenship, online safety, responsible technology use and basic digital productivity.' => ['Kewarganegaraan digital, keselamatan dalam talian, penggunaan teknologi secara bertanggungjawab dan produktiviti digital asas.', '数字公民素养、网络安全、负责任的技术使用及基础数字生产力。', 'டிஜிட்டல் குடியுரிமை, இணையப் பாதுகாப்பு, பொறுப்பான தொழில்நுட்பப் பயன்பாடு மற்றும் அடிப்படை டிஜிட்டல் உற்பத்தித்திறன்.'],
    'Artificial Intelligence Fundamentals' => ['Asas Kecerdasan Buatan', '人工智能基础', 'செயற்கை நுண்ணறிவின் அடிப்படைகள்'],
    'Introduction to AI, prompting, AI-assisted learning, responsible AI use and practical school-level applications.' => ['Pengenalan AI, penulisan arahan, pembelajaran berbantu AI, penggunaan AI secara bertanggungjawab dan aplikasi praktikal peringkat sekolah.', '人工智能入门、提示词编写、AI 辅助学习、负责任的 AI 使用及校级实践应用。', 'AI அறிமுகம், அறிவுறுத்தல் எழுதுதல், AI உதவியுடனான கற்றல், பொறுப்பான AI பயன்பாடு மற்றும் பள்ளி அளவிலான நடைமுறைப் பயன்பாடுகள்.'],
    'Coding & Computational Thinking' => ['Pengaturcaraan dan Pemikiran Komputasional', '编程与计算思维', 'நிரலாக்கமும் கணினிசார் சிந்தனையும்'],
    'Problem-solving, logic, basic coding concepts and computational thinking through guided activities.' => ['Penyelesaian masalah, logik, konsep asas pengaturcaraan dan pemikiran komputasional melalui aktiviti berpandu.', '通过指导活动学习解决问题、逻辑、基础编程概念及计算思维。', 'வழிகாட்டப்பட்ட செயல்பாடுகள் மூலம் சிக்கல் தீர்த்தல், தர்க்கம், அடிப்படை நிரலாக்கக் கருத்துகள் மற்றும் கணினிசார் சிந்தனை.'],
    'STEM, TVET & Simulation' => ['STEM, TVET dan Simulasi', 'STEM、TVET 与模拟', 'STEM, TVET மற்றும் உருவகப்படுத்தல்'],
    'Applied STEM, technical concepts, simulation-based learning and exposure to TVET pathways.' => ['STEM gunaan, konsep teknikal, pembelajaran berasaskan simulasi dan pendedahan kepada laluan TVET.', '应用 STEM、技术概念、模拟学习及 TVET 教育途径介绍。', 'பயன்பாட்டு STEM, தொழில்நுட்பக் கருத்துகள், உருவகப்படுத்தல் சார்ந்த கற்றல் மற்றும் TVET கல்விப் பாதைகள் பற்றிய அறிமுகம்.'],
    'Innovation & Project Development' => ['Inovasi dan Pembangunan Projek', '创新与项目开发', 'புத்தாக்கமும் திட்ட மேம்பாடும்'],
    'Idea generation, problem definition, prototyping, teamwork and presentation of student projects.' => ['Penjanaan idea, takrif masalah, pembinaan prototaip, kerja berpasukan dan pembentangan projek murid.', '创意生成、问题定义、原型制作、团队合作及学生项目展示。', 'யோசனை உருவாக்கம், சிக்கலை வரையறுத்தல், முன்மாதிரி உருவாக்கம், குழுப்பணி மற்றும் மாணவர் திட்டங்களை வழங்குதல்.'],
    'Esports Skills & Performance' => ['Kemahiran dan Prestasi E-Sukan', '电子竞技技能与表现', 'மின்னணு விளையாட்டுத் திறன்களும் செயல்திறனும்'],
    'Game strategy, teamwork, sportsmanship, tournament preparation, gameplay review and performance improvement.' => ['Strategi permainan, kerja berpasukan, semangat kesukanan, persediaan kejohanan, ulasan permainan dan peningkatan prestasi.', '游戏策略、团队合作、体育精神、赛事准备、对局复盘与表现提升。', 'விளையாட்டு உத்தி, குழுப்பணி, விளையாட்டு நெறிமுறை, போட்டித் தயாரிப்பு, ஆட்ட மதிப்பாய்வு மற்றும் செயல்திறன் மேம்பாடு.'],
    'School Development Support' => ['Sokongan Pembangunan Sekolah', '学校发展支持', 'பள்ளி மேம்பாட்டு ஆதரவு'],
    'Equipment eligibility' => ['Kelayakan peralatan', '设备领取资格', 'உபகரணத் தகுதி'],
    'Equipment Eligibility' => ['Kelayakan Peralatan', '设备领取资格', 'உபகரணத் தகுதி'],
    'Participating schools receive programme equipment in stages as student participation grows, with PlayStation 5 and account activation released after the active-participant requirement is achieved.' => ['Sekolah yang menyertai menerima peralatan program secara berperingkat apabila penyertaan murid meningkat. PlayStation 5 dan pengaktifan akaun diberikan selepas syarat peserta aktif dipenuhi.', '参与学校随学生参与人数增长分阶段领取设备，达到活跃参与者人数要求后才发放 PlayStation 5 与账户激活资料。', 'மாணவர் பங்கேற்பு அதிகரிக்கும்போது பள்ளிகளுக்குத் திட்ட உபகரணங்கள் கட்டங்களாக வழங்கப்படும். செயலில் உள்ள பங்கேற்பாளர்களுக்கான நிபந்தனை பூர்த்தியான பிறகே PlayStation 5 மற்றும் கணக்கு செயல்படுத்தல் வழங்கப்படும்.'],
    '10 registered participants' => ['10 peserta berdaftar', '10名已注册参与者', 'பதிவுசெய்த 10 பங்கேற்பாளர்கள்'],
    'Programme equipment is released in stages based on student participation recorded in the portal.' => ['Peralatan program diberikan secara berperingkat berdasarkan penyertaan murid yang direkodkan dalam portal.', '设备根据门户中记录的学生参与情况分阶段发放。', 'இணையதளத்தில் பதிவான மாணவர் பங்கேற்பின் அடிப்படையில் திட்ட உபகரணங்கள் கட்டங்களாக வழங்கப்படும்.'],
    'After 10 participants:' => ['Selepas 10 peserta:', '达到10名参与者后：', '10 பங்கேற்பாளர்களுக்குப் பிறகு:'],
    'Programme equipment and accessories will be sent to the school.' => ['Peralatan dan aksesori program akan dihantar ke sekolah.', '计划设备和配件将送至学校。', 'திட்ட உபகரணங்களும் துணைப்பொருட்களும் பள்ளிக்கு அனுப்பப்படும்.'],
    'After 30 active participants:' => ['Selepas 30 peserta aktif:', '达到30名活跃参与者后：', 'செயலில் உள்ள 30 பங்கேற்பாளர்களுக்குப் பிறகு:'],
    'The PlayStation 5 and account activation details will be sent to the school.' => ['PlayStation 5 dan maklumat pengaktifan akaun akan dihantar ke sekolah.', 'PlayStation 5 与账户激活资料将送至学校。', 'PlayStation 5 மற்றும் கணக்கு செயல்படுத்தல் விவரங்கள் பள்ளிக்கு அனுப்பப்படும்.'],
    'High-end workstation:' => ['Stesen kerja berprestasi tinggi:', '高性能工作站：', 'உயர்திறன் கணினிப் பணிநிலையம்:'],
    'Schools receive 1 workstation for every 100 active students for STEM, AI, simulation and digital innovation activities.' => ['Sekolah menerima 1 stesen kerja bagi setiap 100 murid aktif untuk aktiviti STEM, AI, simulasi dan inovasi digital.', '学校每有100名活跃学生可获得1台工作站，用于 STEM、AI、模拟与数字创新活动。', 'STEM, AI, உருவகப்படுத்தல் மற்றும் டிஜிட்டல் புத்தாக்கச் செயல்பாடுகளுக்காக ஒவ்வொரு 100 செயலில் உள்ள மாணவர்களுக்கும் பள்ளிக்கு ஒரு கணினிப் பணிநிலையம் வழங்கப்படும்.'],
    'School Reference Eligibility' => ['Kelayakan Rujukan Sekolah', '学校推荐资格', 'பள்ளிப் பரிந்துரைத் தகுதி'],
    'Grow the programme network' => ['Luaskan rangkaian program', '扩展计划网络', 'திட்ட வலையமைப்பை விரிவுபடுத்துதல்'],
    'Reference eligibility requires:' => ['Syarat kelayakan rujukan:', '推荐资格要求：', 'பரிந்துரைத் தகுதிக்கான நிபந்தனைகள்:'],
    'The referring school has at least 5 registered students.' => ['Sekolah perujuk mempunyai sekurang-kurangnya 5 murid berdaftar.', '推荐学校至少有5名已注册学生。', 'பரிந்துரைக்கும் பள்ளியில் குறைந்தது 5 பதிவு செய்யப்பட்ட மாணவர்கள் இருக்க வேண்டும்.'],
    'At least 2 schools use it as their referrer.' => ['Sekurang-kurangnya 2 sekolah menggunakan sekolah tersebut sebagai perujuk.', '至少2所学校将其列为推荐学校。', 'குறைந்தது 2 பள்ளிகள் அதைப் பரிந்துரைக்கும் பள்ளியாகப் பதிவு செய்ய வேண்டும்.'],
    'At least 2 referred schools each have 30 active students.' => ['Sekurang-kurangnya 2 sekolah yang dirujuk masing-masing mempunyai 30 murid aktif.', '至少2所被推荐学校各有30名活跃学生。', 'பரிந்துரைக்கப்பட்ட குறைந்தது 2 பள்ளிகளில் தலா 30 செயலில் உள்ள மாணவர்கள் இருக்க வேண்டும்.'],
    '1 set PlayStation 5' => ['1 set PlayStation 5', '1套 PlayStation 5', '1 PlayStation 5 தொகுப்பு'],
    '1 console, 2 controllers, 1 PS Camera and 43-inch digital TV.' => ['1 konsol, 2 alat kawalan, 1 PS Camera dan TV digital 43 inci.', '1台主机、2个控制器、1个 PS Camera 及43英寸数字电视。', '1 விளையாட்டுக் கருவி, 2 கட்டுப்படுத்திகள், 1 PS Camera மற்றும் 43 அங்குல டிஜிட்டல் தொலைக்காட்சி.'],
    'Student & Teacher Recognition' => ['Pengiktirafan Murid dan Guru', '学生与教师表彰', 'மாணவர் மற்றும் ஆசிரியர் அங்கீகாரம்'],
    'STEM & Esports Certificates' => ['Sijil STEM dan E-Sukan', 'STEM 与电子竞技证书', 'STEM மற்றும் மின்னணு விளையாட்டுச் சான்றிதழ்கள்'],
    'Students and school team teachers can receive programme certificates recognising participation, learning, coordination and development across STEM, digital learning and esports activities.' => ['Murid dan guru pasukan sekolah boleh menerima sijil program yang mengiktiraf penyertaan, pembelajaran, penyelarasan dan pembangunan dalam aktiviti STEM, pembelajaran digital dan e-sukan.', '学生与学校团队教师可获得计划证书，以表彰在 STEM、数字学习和电子竞技活动中的参与、学习、协调与发展。', 'STEM, டிஜிட்டல் கற்றல் மற்றும் மின்னணு விளையாட்டுச் செயல்பாடுகளில் பங்கேற்பு, கற்றல், ஒருங்கிணைப்பு மற்றும் வளர்ச்சியை அங்கீகரிக்கும் திட்டச் சான்றிதழ்களை மாணவர்களும் பள்ளிக் குழு ஆசிரியர்களும் பெறலாம்.'],
    'Student STEM & Esports Certificate' => ['Sijil STEM dan E-Sukan Murid', '学生 STEM 与电子竞技证书', 'மாணவர் STEM மற்றும் மின்னணு விளையாட்டுச் சான்றிதழ்'],
    'Recognition of learning module participation, STEM and digital activities, esports participation, teamwork and sportsmanship.' => ['Pengiktirafan penyertaan modul pembelajaran, aktiviti STEM dan digital, e-sukan, kerja berpasukan dan semangat kesukanan.', '表彰学习模块参与、STEM 与数字活动、电子竞技参与、团队合作及体育精神。', 'கற்றல் தொகுதிப் பங்கேற்பு, STEM மற்றும் டிஜிட்டல் செயல்பாடுகள், மின்னணு விளையாட்டுப் பங்கேற்பு, குழுப்பணி மற்றும் விளையாட்டு நெறிமுறைக்கான அங்கீகாரம்.'],
    'Teacher STEM & Esports Certificate' => ['Sijil STEM dan E-Sukan Guru', '教师 STEM 与电子竞技证书', 'ஆசிரியர் STEM மற்றும் மின்னணு விளையாட்டுச் சான்றிதழ்'],
    'Recognition of programme coordination, student supervision, learning support, school activities and events participation.' => ['Pengiktirafan penyelarasan program, penyeliaan murid, sokongan pembelajaran serta penyertaan dalam aktiviti dan acara sekolah.', '表彰计划协调、学生指导、学习支持及学校活动参与。', 'திட்ட ஒருங்கிணைப்பு, மாணவர் மேற்பார்வை, கற்றல் ஆதரவு, பள்ளிச் செயல்பாடுகள் மற்றும் நிகழ்வுகளில் பங்கேற்புக்கான அங்கீகாரம்.'],
    'Digital Certificate Access' => ['Akses Sijil Digital', '数字证书获取', 'டிஜிட்டல் சான்றிதழ் அணுகல்'],
    'Eligible students and teachers can sign in to the portal to access available programme certificates.' => ['Murid dan guru yang layak boleh log masuk ke portal untuk mengakses sijil program yang tersedia.', '符合资格的学生和教师可登录门户获取现有计划证书。', 'தகுதியான மாணவர்களும் ஆசிரியர்களும் இணையதளத்தில் உள்நுழைந்து கிடைக்கும் திட்டச் சான்றிதழ்களை அணுகலாம்.'],
    'View Certificates' => ['Lihat Sijil', '查看证书', 'சான்றிதழ்களைப் பார்க்கவும்'],
    'Frequently Asked Questions' => ['Soalan Lazim', '常见问题', 'அடிக்கடி கேட்கப்படும் கேள்விகள்'],
    'Updated with the latest programme participation, fee, equipment and certificate information.' => ['Dikemas kini dengan maklumat terkini penyertaan, yuran, peralatan dan sijil program.', '已更新计划参与、费用、设备及证书的最新信息。', 'திட்டப் பங்கேற்பு, கட்டணம், உபகரணங்கள் மற்றும் சான்றிதழ்கள் பற்றிய சமீபத்திய தகவல்களுடன் புதுப்பிக்கப்பட்டது.'],
    'Browse FAQs' => ['Lihat Soalan Lazim', '浏览常见问题', 'அடிக்கடி கேட்கப்படும் கேள்விகளைப் பார்க்கவும்'],
    'Question' => ['Soalan', '问题', 'கேள்வி'],
    'Answer' => ['Jawapan', '答案', 'பதில்'],
    'Search schools:' => ['Cari sekolah:', '搜索学校：', 'பள்ளிகளைத் தேடவும்:'],
    'Search FAQ:' => ['Cari soalan lazim:', '搜索常见问题：', 'கேள்விகளைத் தேடவும்:'],
    'Showing _START_–_END_ of _TOTAL_ records' => ['Memaparkan _START_–_END_ daripada _TOTAL_ rekod', '显示第 _START_–_END_ 条，共 _TOTAL_ 条记录', '_TOTAL_ பதிவுகளில் _START_–_END_ காட்டப்படுகிறது'],
    'Showing 0 records' => ['Memaparkan 0 rekod', '显示0条记录', '0 பதிவுகள் காட்டப்படுகின்றன'],
    'No matching records found' => ['Tiada rekod sepadan ditemui', '未找到匹配记录', 'பொருந்தும் பதிவுகள் இல்லை'],
    'Previous' => ['Sebelumnya', '上一页', 'முந்தையது'],
    'No data available in table' => ['Tiada data dalam jadual', '表中暂无数据', 'அட்டவணையில் தரவு இல்லை'],
    '(filtered from _MAX_ total records)' => ['(ditapis daripada _MAX_ jumlah rekod)', '（从 _MAX_ 条记录筛选）', '(_MAX_ மொத்த பதிவுகளில் வடிகட்டப்பட்டது)'],
    'What is the programme?' => ['Apakah program ini?', '这是什么计划？', 'இந்தத் திட்டம் என்ன?'],
    'How much is the student participation fee?' => ['Berapakah yuran penyertaan murid?', '学生参与费是多少？', 'மாணவர் பங்கேற்புக் கட்டணம் எவ்வளவு?'],
    'When will the school receive equipment?' => ['Bilakah sekolah akan menerima peralatan?', '学校何时收到设备？', 'பள்ளிக்கு உபகரணங்கள் எப்போது கிடைக்கும்?'],
    'When will the school receive the PlayStation 5 and account activation?' => ['Bilakah sekolah akan menerima PlayStation 5 dan pengaktifan akaun?', '学校何时收到 PlayStation 5 和账户激活资料？', 'பள்ளிக்கு PlayStation 5 மற்றும் கணக்கு செயல்படுத்தல் எப்போது கிடைக்கும்?'],
    'How do students access their certificates?' => ['Bagaimanakah murid mengakses sijil mereka?', '学生如何获取证书？', 'மாணவர்கள் தங்கள் சான்றிதழ்களை எவ்வாறு அணுகுவது?'],
    'What learning and activities are included?' => ['Apakah pembelajaran dan aktiviti yang disertakan?', '包含哪些学习内容和活动？', 'எந்தக் கற்றலும் செயல்பாடுகளும் இதில் அடங்கும்?'],
    'Can students join tournaments?' => ['Bolehkah murid menyertai kejohanan?', '学生可以参加锦标赛吗？', 'மாணவர்கள் போட்டித் தொடர்களில் பங்கேற்க முடியுமா?'],
    'Who coordinates the programme at school?' => ['Siapakah yang menyelaras program di sekolah?', '谁负责在学校协调本计划？', 'பள்ளியில் திட்டத்தை யார் ஒருங்கிணைக்கிறார்கள்?'],
    '<p>The programme is a school-based STEM, TVET, AI, simulation, digital innovation and esports talent development initiative combining structured learning, activities, attendance, certificates and competitions.</p>' => ['<p>Program ini ialah inisiatif pembangunan bakat berasaskan sekolah dalam STEM, TVET, AI, simulasi, inovasi digital dan e-sukan yang menggabungkan pembelajaran berstruktur, aktiviti, kehadiran, sijil dan pertandingan.</p>', '<p>本计划是以学校为基础的 STEM、TVET、人工智能、模拟、数字创新与电子竞技人才发展项目，结合系统化学习、活动、出勤、证书与比赛。</p>', '<p>இது STEM, TVET, AI, உருவகப்படுத்தல், டிஜிட்டல் புத்தாக்கம் மற்றும் மின்னணு விளையாட்டுகளில் திறனை வளர்க்கும் பள்ளி சார்ந்த திட்டமாகும்; முறையான கற்றல், செயல்பாடுகள், வருகை, சான்றிதழ்கள் மற்றும் போட்டிகளை ஒருங்கிணைக்கிறது.</p>'],
    '<p>The student participation fee is <strong>RM100 one time only</strong>.</p>' => ['<p>Yuran penyertaan murid ialah <strong>RM100 sekali sahaja</strong>.</p>', '<p>学生参与费为<strong>一次性 RM100</strong>。</p>', '<p>மாணவர் பங்கேற்புக் கட்டணம் <strong>RM100 ஒருமுறை மட்டுமே</strong>.</p>'],
    '<p>After the school reaches <strong>10 registered participants</strong>, programme equipment and accessories will be sent to the school.</p>' => ['<p>Selepas sekolah mencapai <strong>10 peserta berdaftar</strong>, peralatan dan aksesori program akan dihantar ke sekolah.</p>', '<p>学校达到<strong>10名已注册参与者</strong>后，将收到计划设备及配件。</p>', '<p>பள்ளியில் <strong>10 பங்கேற்பாளர்கள் பதிவு செய்யப்பட்டதும்</strong> திட்ட உபகரணங்களும் துணைப்பொருட்களும் பள்ளிக்கு அனுப்பப்படும்.</p>'],
    '<p>The <strong>PlayStation 5 and account activation details</strong> will be sent only after the school reaches <strong>30 active participants</strong>.</p>' => ['<p><strong>PlayStation 5 dan maklumat pengaktifan akaun</strong> hanya akan dihantar setelah sekolah mencapai <strong>30 peserta aktif</strong>.</p>', '<p>学校达到<strong>30名活跃参与者</strong>后，才会收到<strong>PlayStation 5 和账户激活资料</strong>。</p>', '<p>பள்ளி <strong>30 செயலில் உள்ள பங்கேற்பாளர்களை</strong> அடைந்த பிறகே <strong>PlayStation 5 மற்றும் கணக்கு செயல்படுத்தல் விவரங்கள்</strong> அனுப்பப்படும்.</p>'],
    '<p>Eligible students and teachers can sign in through the programme login page and access available certificates from their portal.</p>' => ['<p>Murid dan guru yang layak boleh log masuk melalui halaman log masuk program dan mengakses sijil yang tersedia dalam portal mereka.</p>', '<p>符合资格的学生和教师可通过计划登录页登录，并在各自门户获取现有证书。</p>', '<p>தகுதியான மாணவர்களும் ஆசிரியர்களும் திட்ட உள்நுழைவுப் பக்கம் வழியாக உள்நுழைந்து தங்கள் இணையதளத்தில் கிடைக்கும் சான்றிதழ்களை அணுகலாம்.</p>'],
    '<p>The programme includes structured learning in digital literacy, AI, coding, STEM, TVET, simulation, innovation and esports, together with attendance tracking, events and competitions.</p>' => ['<p>Program ini merangkumi pembelajaran berstruktur dalam literasi digital, AI, pengaturcaraan, STEM, TVET, simulasi, inovasi dan e-sukan, bersama rekod kehadiran, acara dan pertandingan.</p>', '<p>本计划涵盖数字素养、AI、编程、STEM、TVET、模拟、创新与电子竞技的系统化学习，以及出勤记录、活动和比赛。</p>', '<p>டிஜிட்டல் எழுத்தறிவு, AI, நிரலாக்கம், STEM, TVET, உருவகப்படுத்தல், புத்தாக்கம் மற்றும் மின்னணு விளையாட்டுகளில் முறையான கற்றலுடன் வருகைப் பதிவு, நிகழ்வுகள் மற்றும் போட்டிகளும் அடங்கும்.</p>'],
    '<p>Yes. Eligible students can participate in programme competitions and tournaments published through the portal.</p>' => ['<p>Ya. Murid yang layak boleh menyertai pertandingan dan kejohanan program yang diterbitkan melalui portal.</p>', '<p>可以。符合资格的学生可参加门户公布的计划比赛与锦标赛。</p>', '<p>ஆம். தகுதியான மாணவர்கள் இணையதளத்தில் அறிவிக்கப்பட்ட திட்டப் போட்டிகளிலும் போட்டித் தொடர்களிலும் பங்கேற்கலாம்.</p>'],
    '<p>Each participating school registers a School Team Teacher who coordinates programme participation, student learning and related activities.</p>' => ['<p>Setiap sekolah yang menyertai mendaftarkan seorang Guru Pasukan Sekolah untuk menyelaras penyertaan program, pembelajaran murid dan aktiviti berkaitan.</p>', '<p>每所参与学校注册一名学校团队教师，负责协调计划参与、学生学习及相关活动。</p>', '<p>ஒவ்வொரு பங்கேற்கும் பள்ளியும் திட்டப் பங்கேற்பு, மாணவர் கற்றல் மற்றும் தொடர்புடைய செயல்பாடுகளை ஒருங்கிணைக்கும் பள்ளிக் குழு ஆசிரியரைப் பதிவு செய்கிறது.</p>'],
    '%d of 4 slots contain submitted videos. No external or repeated videos are used.' => ['%d daripada 4 ruang mengandungi video yang dihantar. Tiada video luar atau berulang digunakan.', '4个位置中有 %d 个包含提交的视频。不使用外部或重复视频。', '4 இடங்களில் %d இடங்களில் சமர்ப்பிக்கப்பட்ட காணொளிகள் உள்ளன. வெளிப்புற அல்லது மீண்டும் வரும் காணொளிகள் பயன்படுத்தப்படுவதில்லை.'],
    'Watch %s on YouTube' => ['Tonton %s di YouTube', '在 YouTube 上观看 %s', 'YouTube இல் %s பார்க்கவும்'],
];
